import re
p='docs/STATUS.md'
s=open(p).read()
lines=s.split('\n')
cs=lines.index('## Current state'); nx=lines.index('## Next')
body=lines[cs+1:nx]
# group into top-level bullet blocks
blocks=[]
for l in body:
    if l.startswith('- ') or not blocks: blocks.append([l])
    else: blocks[-1].append(l)
keep=[];moved=[]
for b in blocks:
    m=re.match(r'- \*{0,2}(\d{4}-\d{2}-\d{2})', b[0])
    (moved if m and m.group(1)<'2026-10-09' else keep).append(b)
# trailing blank lines stay with keep
print('moved',len(moved),'kept',len(keep))
for b in moved: print('  M',b[0][:60])
# blocks that had trailing blank lines inside moved?
for b in moved:
    if b[-1].strip()=='' : print('blank-tail in moved', b[0][:40])
